"use client";

/**
 * Folder
 *
 * Standalone forward-facing 2D vector folder with exact 84x61 proportions, filleted tabs,
 * and punch dots. Silhouette geometry and fillet algorithms adapted from Lucas Markes' hairline:
 * https://github.com/lucasmarkes/hairline
 */

import React from "react";

export interface FolderProps {
  bodyColor?: string;
  darkOutline?: string;
  lightOutline?: string;
  borderWidth?: number | string; // Thickness of the silhouette outline and divider lines (e.g. 1.2, 1, or "1px")
  depth?: boolean | number; // 3D cardstock thickness with offset back face (default: true)
  folderIndex?: number; // 0 to 7 to determine exact tab position and active punch dot
  tabPosition?: "left" | "center" | "right";
  showLines?: boolean; // Set to false to hide the 4 horizontal ruled lines
  className?: string;
  children?: React.ReactNode;
}

// Geometric constants matching @lucasmarkes/hairline riffle-geometry.ts
const W = 84;
const H = 54;
const TW = 22;
const TH = 7;
const TOTAL_H = H + TH + 1; // 62
const TABS = [6, 31, 56]; // Left, Center, Right

function fillet(pts: [number, number][], rs: number[], n = 4): [number, number][] {
  const m = pts.length;
  const out: [number, number][] = [];
  for (let i = 0; i < m; i++) {
    const a = pts[(i + m - 1) % m];
    const p = pts[i];
    const b = pts[(i + 1) % m];
    const la = Math.hypot(a[0] - p[0], a[1] - p[1]);
    const lb = Math.hypot(b[0] - p[0], b[1] - p[1]);
    const t = Math.min(rs[i], la / 2, lb / 2);
    const p1: [number, number] = [p[0] + ((a[0] - p[0]) / la) * t, p[1] + ((a[1] - p[1]) / la) * t];
    const p2: [number, number] = [p[0] + ((b[0] - p[0]) / lb) * t, p[1] + ((b[1] - p[1]) / lb) * t];
    for (let k = 0; k <= n; k++) {
      const s = k / n;
      const w = 1 - s;
      out.push([
        w * w * p1[0] + 2 * w * s * p[0] + s * s * p2[0],
        w * w * p1[1] + 2 * w * s * p[1] + s * s * p2[1],
      ]);
    }
  }
  return out;
}

const r2 = (x: number) => Math.round(x * 100) / 100;
const toSvgPath = (pts: [number, number][]) =>
  "M" + pts.map((p) => r2(p[0]) + " " + r2(p[1])).join("L") + "Z";

function generateFolderSilhouette(t0: number): string {
  const rawPts = fillet(
    [
      [0, 0],
      [W, 0],
      [W, H],
      [t0 + TW, H],
      [t0 + TW, H + TH],
      [t0, H + TH],
      [t0, H],
      [0, H],
    ],
    [1, 1, 3.2, 1.8, 2.4, 2.4, 1.8, 3.2]
  );
  // Invert Y so the tab is at the top in SVG
  const pts: [number, number][] = rawPts.map(([x, y]) => [x, TOTAL_H - y]);
  return toSvgPath(pts);
}

// Pre-computed silhouette paths for each tab position (Left = 0, Center = 1, Right = 2)
const SILHOUETTES = [
  generateFolderSilhouette(TABS[0]),
  generateFolderSilhouette(TABS[1]),
  generateFolderSilhouette(TABS[2]),
];

/**
 * Folder
 * Renders a folder card facing forward in 2D vector format,
 * using geometric vector paths, tab fillets, ruled lines, and punch dots.
 */
export function Folder({
  bodyColor = "#E54F10",
  darkOutline = "#7C2D12",
  lightOutline = "#FED7AA",
  borderWidth = 1.2,
  depth = true,
  folderIndex = 0,
  tabPosition,
  showLines = true,
  className = "w-44 h-auto drop-shadow-sm",
  children,
}: FolderProps) {
  // Determine tab index: 0 = left, 1 = center, 2 = right
  let tabIdx = 1;
  if (tabPosition === "left") tabIdx = 0;
  else if (tabPosition === "center") tabIdx = 1;
  else if (tabPosition === "right") tabIdx = 2;
  else {
    // Matches tab cycle: t0 = TABS[(8 - 1 - i) % 3]
    tabIdx = (7 - (folderIndex % 8)) % 3;
  }

  const t0 = TABS[tabIdx];
  const silhouettePath = SILHOUETTES[tabIdx];
  // Active dot index matching hairline (k === n - 1 where n = 8 - i)
  const activeDotIndex = 7 - (folderIndex % 8);

  const dividerStrokeWidth =
    typeof borderWidth === "number" ? Math.max(0.75, borderWidth * 0.75) : borderWidth;

  // 3D cardstock thickness offset (back face shifted up and to the right)
  const depthValue = typeof depth === "number" ? depth : depth ? 1 : 0;
  const depthOffsetX = depthValue * 0.95;
  const depthOffsetY = -depthValue * 0.95;

  const svgContent = (
    <svg
      viewBox={depthValue > 0 ? "-2 -2 89 66" : "-2 -1 88 65"}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={children ? "h-full w-full" : className}
    >
      {/* 0. 3D Back Face (Cardstock Thickness Bevel with Light Outline) */}
      {depthValue > 0 && (
        <path
          d={silhouettePath}
          transform={`translate(${depthOffsetX}, ${depthOffsetY})`}
          fill={bodyColor}
          stroke={lightOutline}
          strokeWidth={borderWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinejoin="round"
        />
      )}

      {/* 1. Main Folder Silhouette Face (Front Face with Dark Outline) */}
      <path
        d={silhouettePath}
        fill={bodyColor}
        stroke={darkOutline}
        strokeWidth={borderWidth}
        vectorEffect="non-scaling-stroke"
        strokeLinejoin="round"
      />

      {/* 2. Top Header Divider Line below the tab */}
      {showLines && (
        <line
          x1="6"
          y1="19"
          x2="78"
          y2="19"
          stroke={darkOutline}
          strokeWidth={dividerStrokeWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinecap="round"
        />
      )}

      {/* 3. Four Horizontal Ruled Lines */}
      {showLines &&
        [26, 33, 40, 47].map((y) => (
          <line
            key={y}
            x1="6"
            y1={y}
            x2="78"
            y2={y}
            stroke={lightOutline}
            strokeWidth={dividerStrokeWidth}
            vectorEffect="non-scaling-stroke"
            strokeLinecap="round"
          />
        ))}

      {/* 4. Eight Punch Dots on the Tab (2 rows of 4) */}
      {Array.from({ length: 8 }).map((_, k) => {
        const cx = t0 + TW / 2 + ((k % 4) - 1.5) * 3.6;
        const cy = Math.floor(k / 4) === 0 ? 3.2 : 5.8;
        const isActive = k === activeDotIndex;

        return (
          <circle
            key={k}
            cx={cx}
            cy={cy}
            r={1.05}
            fill={isActive ? darkOutline : lightOutline}
            stroke="none"
          />
        );
      })}
    </svg>
  );

  if (!children) {
    return svgContent;
  }

  return (
    <div className={`relative ${className}`}>
      {svgContent}
      <div className="absolute inset-0 flex flex-col">{children}</div>
    </div>
  );
}

"use client";

/**
 * Folder
 *
 * Standalone forward-facing 2D vector folder with exact 84x61 proportions, filleted tabs,
 * and punch dots. Silhouette geometry and fillet algorithms adapted from Lucas Markes' hairline:
 * https://github.com/lucasmarkes/hairline
 */

import React from "react";

export interface FolderProps {
  bodyColor?: string;
  darkOutline?: string;
  lightOutline?: string;
  borderWidth?: number | string; // Thickness of the silhouette outline and divider lines (e.g. 1.2, 1, or "1px")
  depth?: boolean | number; // 3D cardstock thickness with offset back face (default: true)
  folderIndex?: number; // 0 to 7 to determine exact tab position and active punch dot
  tabPosition?: "left" | "center" | "right";
  showLines?: boolean; // Set to false to hide the 4 horizontal ruled lines
  className?: string;
  children?: React.ReactNode;
}

// Geometric constants matching @lucasmarkes/hairline riffle-geometry.ts
const W = 84;
const H = 54;
const TW = 22;
const TH = 7;
const TOTAL_H = H + TH + 1; // 62
const TABS = [6, 31, 56]; // Left, Center, Right

function fillet(pts: [number, number][], rs: number[], n = 4): [number, number][] {
  const m = pts.length;
  const out: [number, number][] = [];
  for (let i = 0; i < m; i++) {
    const a = pts[(i + m - 1) % m];
    const p = pts[i];
    const b = pts[(i + 1) % m];
    const la = Math.hypot(a[0] - p[0], a[1] - p[1]);
    const lb = Math.hypot(b[0] - p[0], b[1] - p[1]);
    const t = Math.min(rs[i], la / 2, lb / 2);
    const p1: [number, number] = [p[0] + ((a[0] - p[0]) / la) * t, p[1] + ((a[1] - p[1]) / la) * t];
    const p2: [number, number] = [p[0] + ((b[0] - p[0]) / lb) * t, p[1] + ((b[1] - p[1]) / lb) * t];
    for (let k = 0; k <= n; k++) {
      const s = k / n;
      const w = 1 - s;
      out.push([
        w * w * p1[0] + 2 * w * s * p[0] + s * s * p2[0],
        w * w * p1[1] + 2 * w * s * p[1] + s * s * p2[1],
      ]);
    }
  }
  return out;
}

const r2 = (x: number) => Math.round(x * 100) / 100;
const toSvgPath = (pts: [number, number][]) =>
  "M" + pts.map((p) => r2(p[0]) + " " + r2(p[1])).join("L") + "Z";

function generateFolderSilhouette(t0: number): string {
  const rawPts = fillet(
    [
      [0, 0],
      [W, 0],
      [W, H],
      [t0 + TW, H],
      [t0 + TW, H + TH],
      [t0, H + TH],
      [t0, H],
      [0, H],
    ],
    [1, 1, 3.2, 1.8, 2.4, 2.4, 1.8, 3.2]
  );
  // Invert Y so the tab is at the top in SVG
  const pts: [number, number][] = rawPts.map(([x, y]) => [x, TOTAL_H - y]);
  return toSvgPath(pts);
}

// Pre-computed silhouette paths for each tab position (Left = 0, Center = 1, Right = 2)
const SILHOUETTES = [
  generateFolderSilhouette(TABS[0]),
  generateFolderSilhouette(TABS[1]),
  generateFolderSilhouette(TABS[2]),
];

/**
 * Folder
 * Renders a folder card facing forward in 2D vector format,
 * using geometric vector paths, tab fillets, ruled lines, and punch dots.
 */
export function Folder({
  bodyColor = "#E54F10",
  darkOutline = "#7C2D12",
  lightOutline = "#FED7AA",
  borderWidth = 1.2,
  depth = true,
  folderIndex = 0,
  tabPosition,
  showLines = true,
  className = "w-44 h-auto drop-shadow-sm",
  children,
}: FolderProps) {
  // Determine tab index: 0 = left, 1 = center, 2 = right
  let tabIdx = 1;
  if (tabPosition === "left") tabIdx = 0;
  else if (tabPosition === "center") tabIdx = 1;
  else if (tabPosition === "right") tabIdx = 2;
  else {
    // Matches tab cycle: t0 = TABS[(8 - 1 - i) % 3]
    tabIdx = (7 - (folderIndex % 8)) % 3;
  }

  const t0 = TABS[tabIdx];
  const silhouettePath = SILHOUETTES[tabIdx];
  // Active dot index matching hairline (k === n - 1 where n = 8 - i)
  const activeDotIndex = 7 - (folderIndex % 8);

  const dividerStrokeWidth =
    typeof borderWidth === "number" ? Math.max(0.75, borderWidth * 0.75) : borderWidth;

  // 3D cardstock thickness offset (back face shifted up and to the right)
  const depthValue = typeof depth === "number" ? depth : depth ? 1 : 0;
  const depthOffsetX = depthValue * 0.95;
  const depthOffsetY = -depthValue * 0.95;

  const svgContent = (
    <svg
      viewBox={depthValue > 0 ? "-2 -2 89 66" : "-2 -1 88 65"}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={children ? "h-full w-full" : className}
    >
      {/* 0. 3D Back Face (Cardstock Thickness Bevel with Light Outline) */}
      {depthValue > 0 && (
        <path
          d={silhouettePath}
          transform={`translate(${depthOffsetX}, ${depthOffsetY})`}
          fill={bodyColor}
          stroke={lightOutline}
          strokeWidth={borderWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinejoin="round"
        />
      )}

      {/* 1. Main Folder Silhouette Face (Front Face with Dark Outline) */}
      <path
        d={silhouettePath}
        fill={bodyColor}
        stroke={darkOutline}
        strokeWidth={borderWidth}
        vectorEffect="non-scaling-stroke"
        strokeLinejoin="round"
      />

      {/* 2. Top Header Divider Line below the tab */}
      {showLines && (
        <line
          x1="6"
          y1="19"
          x2="78"
          y2="19"
          stroke={darkOutline}
          strokeWidth={dividerStrokeWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinecap="round"
        />
      )}

      {/* 3. Four Horizontal Ruled Lines */}
      {showLines &&
        [26, 33, 40, 47].map((y) => (
          <line
            key={y}
            x1="6"
            y1={y}
            x2="78"
            y2={y}
            stroke={lightOutline}
            strokeWidth={dividerStrokeWidth}
            vectorEffect="non-scaling-stroke"
            strokeLinecap="round"
          />
        ))}

      {/* 4. Eight Punch Dots on the Tab (2 rows of 4) */}
      {Array.from({ length: 8 }).map((_, k) => {
        const cx = t0 + TW / 2 + ((k % 4) - 1.5) * 3.6;
        const cy = Math.floor(k / 4) === 0 ? 3.2 : 5.8;
        const isActive = k === activeDotIndex;

        return (
          <circle
            key={k}
            cx={cx}
            cy={cy}
            r={1.05}
            fill={isActive ? darkOutline : lightOutline}
            stroke="none"
          />
        );
      })}
    </svg>
  );

  if (!children) {
    return svgContent;
  }

  return (
    <div className={`relative ${className}`}>
      {svgContent}
      <div className="absolute inset-0 flex flex-col">{children}</div>
    </div>
  );
}

import React from "react";

export type ButtonVariant = "default" | "dark" | "orange" | "emerald";
export type ButtonSize = "sm" | "default" | "lg";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  depth?: string;
  radius?: string;
  faceColor?: string;
  faceHighlight?: string;
  contentColor?: string;
  baseColor?: string;
  baseShadow?: string;
  href?: string;
  target?: string;
  rel?: string;
  children: React.ReactNode;
}

const VARIANTS = {
  default: {
    face: "#4a4a46",
    highlight: "#64645e",
    content: "#eeeeec",
    base: "#292926",
    shadow: "#141412",
  },
  dark: {
    face: "#1e2024",
    highlight: "#353840",
    content: "#ffffff",
    base: "#111215",
    shadow: "#09090b",
  },
  orange: {
    face: "#e54f10",
    highlight: "#fb713b",
    content: "#ffffff",
    base: "#9a3412",
    shadow: "#7c2d12",
  },
  emerald: {
    face: "#059669",
    highlight: "#10b981",
    content: "#ffffff",
    base: "#047857",
    shadow: "#064e3b",
  },
};

const SIZES = {
  sm: {
    depth: "4px",
    radius: "0.5rem",
    inner: "h-7 gap-1 px-2.5 text-[11px]",
  },
  default: {
    depth: "6px",
    radius: "0.75rem",
    inner: "h-8 gap-1.5 px-3 text-xs",
  },
  lg: {
    depth: "7px",
    radius: "0.875rem",
    inner: "h-10 gap-2 px-4 text-sm",
  },
};

export const Button = React.forwardRef<HTMLButtonElement & HTMLAnchorElement, ButtonProps>(
  (
    {
      variant = "default",
      size = "default",
      depth,
      radius,
      faceColor,
      faceHighlight,
      contentColor,
      baseColor,
      baseShadow,
      href,
      target,
      rel,
      children,
      className = "",
      style,
      disabled,
      ...props
    },
    ref
  ) => {
    const v = VARIANTS[variant] || VARIANTS.default;
    const s = SIZES[size] || SIZES.default;

    const actualDepth = depth || s.depth;
    const actualRadius = radius || s.radius;

    const customStyles: Record<string, string> = {
      "--tactile-depth": actualDepth,
      "--tactile-radius": actualRadius,
      "--tactile-face": faceColor || v.face,
      "--tactile-face-highlight": faceHighlight || v.highlight,
      "--tactile-content": contentColor || v.content,
      "--tactile-base": baseColor || v.base,
      "--tactile-base-shadow": baseShadow || v.shadow,
    };

    const combinedStyle = {
      ...customStyles,
      ...style,
    } as React.CSSProperties;

    const baseClasses = `group/tactile relative inline-grid w-max shrink-0 cursor-pointer select-none border-0 bg-transparent p-0 pb-[var(--tactile-depth)] font-inherit leading-none focus-visible:rounded-[var(--tactile-radius)] focus-visible:outline-2 focus-visible:outline-slate-700 focus-visible:outline-offset-2 disabled:pointer-events-none disabled:opacity-45 aria-disabled:pointer-events-none aria-disabled:opacity-45 ${className}`;

    const innerContent = (
      <>
        {/* 3D Base extrusion shadow */}
        <span className="absolute inset-x-0 top-[var(--tactile-depth)] bottom-0 rounded-[var(--tactile-radius)] bg-[var(--tactile-base)] shadow-[inset_0_-1px_0_var(--tactile-base-shadow)]" />

        {/* 3D Surface Face with mechanical push kinematics */}
        <span
          className={`relative flex items-center justify-center rounded-[var(--tactile-radius)] bg-[var(--tactile-face)] font-medium text-[var(--tactile-content)] shadow-[inset_0_1px_0_var(--tactile-face-highlight)] transition-transform duration-150 [transition-timing-function:cubic-bezier(0.23,1,0.32,1)] group-active/tactile:translate-y-[var(--tactile-depth)] motion-reduce:transform-none motion-reduce:transition-none [@media(hover:hover)_and_(pointer:fine)]:group-hover/tactile:translate-y-0.5 ${s.inner}`}
        >
          {children}
        </span>
      </>
    );

    if (href) {
      return (
        <a
          ref={ref as React.Ref<HTMLAnchorElement>}
          href={href}
          target={target}
          rel={target === "_blank" ? rel || "noopener noreferrer" : rel}
          style={combinedStyle}
          className={baseClasses}
          aria-disabled={disabled}
        >
          {innerContent}
        </a>
      );
    }

    return (
      <button
        ref={ref as React.Ref<HTMLButtonElement>}
        type="button"
        style={combinedStyle}
        className={baseClasses}
        disabled={disabled}
        {...props}
      >
        {innerContent}
      </button>
    );
  }
);

Button.displayName = "Button";

"use client";

/**
 * SelectBar (Glass Bar)
 *
 * A refined physical frosted glass selector and navigation dock with
 * two-phase mercury stretch dilation and overshoot landing kinematics.
 */

import React, { useEffect, useLayoutEffect, useRef, useState, useCallback } from "react";

const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

/* ── elastic motion tuning (exact curves from lab/motion) ── */
const rate = (speed: number) => 1.6 - (speed / 100) * 1.2;

const overshoot = (bounce: number, tuned: number) =>
  Number((1 + (bounce / 100) * (tuned - 1) * 2).toFixed(3));

const curve = (bounce: number, tuned: number, x1 = 0.28, x2 = 0.36) =>
  `cubic-bezier(${x1}, ${overshoot(bounce, tuned)}, ${x2}, 1)`;

const settle = (bounce: number) => ({
  move: curve(bounce, 1.28, 0.28, 0.36),
  size: curve(bounce, 1.34, 0.24, 0.38),
});

type Ind = { p: number; s: number };

export interface SelectBarItem<T extends string = string> {
  key: T;
  label?: string;
  icon?: React.ReactNode;
  color?: string;
  darkOutline?: string;
  title?: string;
  showLabel?: boolean;
}

export interface SelectBarProps<T extends string = string> {
  items: SelectBarItem<T>[];
  value?: T;
  defaultValue?: T;
  onChange?: (value: T) => void;
  size?: "xs" | "sm" | "default";
  dilate?: number;
  bounce?: number;
  speed?: number;
  hug?: number;
  className?: string;
  ariaLabel?: string;
  // Backward compatibility props
  variant?: "glass" | "swatches" | "pill";
  axis?: "row" | "column";
  corner?: number;
}

export function SelectBar<T extends string = string>({
  items,
  value,
  defaultValue,
  onChange,
  size = "sm",
  dilate = 100,
  bounce = 50,
  speed = 50,
  hug,
  className = "",
  ariaLabel = "Navigation",
}: SelectBarProps<T>) {
  const initialKey = value ?? defaultValue ?? items[0]?.key;
  const [active, setActive] = useState<T>(initialKey);

  const trackRef = useRef<HTMLElement | null>(null);
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [ind, setInd] = useState<Ind | null>(null);
  const [phase, setPhase] = useState<"idle" | "stretch" | "settle">("idle");
  const indRef = useRef<Ind | null>(null);
  const timer = useRef<number | undefined>(undefined);

  const hasSwatches = items.some((item) => Boolean(item.color));
  const defaultHug = hasSwatches ? 3 : size === "xs" ? 3 : size === "sm" ? 4 : 6;
  const actualHug = hug !== undefined ? hug : defaultHug;

  const measure = useCallback((k: string): Ind | null => {
    const el = refs.current[k];
    if (!el) return null;
    return { p: el.offsetLeft, s: el.offsetWidth };
  }, []);

  const activeRef = useRef<T>(initialKey);
  const prevValueRef = useRef<T | undefined>(value);

  // Exact 2-phase elastic stretch and settle glide
  const select = useCallback(
    (k: T) => {
      if (k === activeRef.current) return;
      activeRef.current = k;
      prevValueRef.current = k;
      const to = measure(k);
      const from = indRef.current;
      setActive(k);

      if (!to) return;
      window.clearTimeout(timer.current);

      if (!from) {
        indRef.current = to;
        setPhase("settle");
        setInd(to);
        return;
      }

      /* Leading edge dilates across the union of slots */
      const start = Math.min(from.p, to.p);
      const end = Math.max(from.p + from.s, to.p + to.s);
      const grow = dilate / 100;

      setPhase("stretch");
      setInd({
        p: to.p + (start - to.p) * grow,
        s: to.s + (end - start - to.s) * grow,
      });

      /* Trailing edge catches up and overshoots on landing */
      timer.current = window.setTimeout(
        () => {
          indRef.current = to;
          setPhase("settle");
          setInd(to);
        },
        150 * rate(speed)
      );
    },
    [dilate, measure, speed]
  );

  // Controlled sync from props.value
  useEffect(() => {
    if (value !== undefined && value !== activeRef.current) {
      select(value);
    }
  }, [value, select]);

  // Initial mount measurement & ResizeObserver
  useIsomorphicLayoutEffect(() => {
    const settleInd = () => {
      const next = measure(activeRef.current);
      if (!next) return;
      indRef.current = next;
      setPhase("idle");
      setInd(next);
    };
    settleInd();

    const ro = new ResizeObserver(settleInd);
    if (trackRef.current) ro.observe(trackRef.current);
    return () => ro.disconnect();
  }, [measure]);

  const curveStyles = settle(bounce);

  const vars = {
    "--nav-pad": `${actualHug}px`,
    "--ind-stretch": `${Math.round(190 * rate(speed))}ms`,
    "--ind-settle": `${Math.round(420 * rate(speed))}ms`,
    "--ind-move": curveStyles.move,
    "--ind-size": curveStyles.size,
  } as React.CSSProperties;

  const style: React.CSSProperties = ind
    ? { transform: `translate3d(${ind.p}px, 0, 0)`, width: ind.s }
    : { opacity: 0 };

  return (
    <>
      <style>{`
        /* ── signature frosted glass dock ──────────────────────── */
        .gnav {
          position: relative;
          background: rgba(255, 255, 255, 0.6);
          -webkit-backdrop-filter: blur(8px) saturate(150%) brightness(100%);
          backdrop-filter: blur(8px) saturate(150%) brightness(100%);
          isolation: isolate;
          color: #0f172a;
          display: inline-flex;
          align-items: center;
          gap: 2px;
          padding: var(--nav-pad);
          border-radius: 999px;
          user-select: none;
          box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, 0.9),
            0 10px 40px rgba(15, 23, 42, 0.08);
        }

        /* Prismatic specular lit rim */
        .gnav::before {
          content: "";
          position: absolute;
          inset: 0;
          border-radius: inherit;
          border: 1px solid transparent;
          pointer-events: none;
          z-index: 3;
          background:
            linear-gradient(
              142deg,
              rgba(255, 255, 255, 0.7) 0%,
              rgba(255, 255, 255, 0.15) 26%,
              rgba(255, 255, 255, 0.05) 62%,
              rgba(255, 255, 255, 0.4) 100%
            ) border-box;
          -webkit-mask:
            linear-gradient(#000 0 0) padding-box,
            linear-gradient(#000 0 0);
          -webkit-mask-composite: xor;
          mask:
            linear-gradient(#000 0 0) padding-box,
            linear-gradient(#000 0 0);
          mask-composite: exclude;
        }

        /* ── two-phase indicator wash ──────────────────────────── */
        .gnav-ind {
          position: absolute;
          top: var(--nav-pad);
          left: 0;
          height: calc(100% - var(--nav-pad) * 2);
          border-radius: 999px;
          background: rgba(0, 0, 0, 0.06);
          border: 0;
          box-shadow: none;
          pointer-events: none;
          will-change: transform, width;
          z-index: 1;
        }

        /* Phase one: leading edge jumps, pill dilates */
        .gnav-ind[data-phase="stretch"] {
          --d: var(--ind-stretch, 190ms);
          transition:
            transform var(--d) cubic-bezier(0.32, 0.72, 0.24, 1),
            width var(--d) cubic-bezier(0.32, 0.72, 0.24, 1);
        }

        /* Phase two: trailing edge catches up, overshoots */
        .gnav-ind[data-phase="settle"] {
          --d: var(--ind-settle, 420ms);
          transition:
            transform var(--d) var(--ind-move, cubic-bezier(0.28, 1.28, 0.36, 1)),
            width var(--d) var(--ind-size, cubic-bezier(0.24, 1.34, 0.38, 1));
        }

        .gnav-ind[data-phase="idle"] {
          transition: none;
        }

        /* ── slots ─────────────────────────────────────────────── */
        .gnav-item {
          position: relative;
          z-index: 2;
          border: 0;
          border-radius: 999px;
          background: none;
          color: #0f172a;
          opacity: 0.5;
          display: flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          transition: opacity 260ms cubic-bezier(0.32, 0.72, 0.24, 1);
          line-height: 1;
        }

        .gnav-item:hover {
          opacity: 0.85;
        }

        .gnav-item[data-active="true"],
        .gnav-item[data-swatch="true"] {
          opacity: 1;
        }

        .gnav-item:focus-visible {
          outline: 1.5px solid #0f172a;
          outline-offset: 2px;
        }
      `}</style>

      <nav
        ref={trackRef as React.RefObject<HTMLElement>}
        className={`gnav ${className}`}
        style={vars}
        aria-label={ariaLabel}
      >
        <span className="gnav-ind" data-phase={phase} style={style} aria-hidden />

        {items.map((item) => {
          const isSelected = active === item.key;
          const isSwatch = Boolean(item.color);
          const isIconOnly = Boolean(item.icon && (!item.label || item.showLabel === false));
          const slotTitle = item.title || item.label || item.key;

          const dim = size === "xs" ? 26 : size === "default" ? 36 : 30;
          const padH = size === "xs" ? 11 : size === "default" ? 16 : 13;

          const slotStyle: React.CSSProperties =
            isSwatch || isIconOnly
              ? {
                  width: `${dim}px`,
                  height: `${dim}px`,
                  minWidth: `${dim}px`,
                  padding: 0,
                  flexShrink: 0,
                }
              : {
                  width: "auto",
                  minWidth: `${dim}px`,
                  height: `${dim}px`,
                  padding: `0 ${padH}px`,
                  whiteSpace: "nowrap",
                  flexShrink: 0,
                };

          return (
            <button
              key={item.key}
              ref={(el) => {
                refs.current[item.key] = el;
              }}
              type="button"
              className="gnav-item"
              data-active={isSelected}
              data-swatch={isSwatch}
              aria-label={slotTitle}
              title={slotTitle}
              aria-current={isSelected ? "page" : undefined}
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                select(item.key);
                onChange?.(item.key);
              }}
              style={slotStyle}
            >
              {item.color ? (
                <span
                  className={`block rounded-full border transition-transform duration-150 ${
                    isSelected ? "scale-110" : "hover:scale-105"
                  }`}
                  style={{
                    backgroundColor: item.color,
                    borderColor: item.darkOutline || item.color,
                    width: size === "xs" ? "12px" : size === "default" ? "16px" : "14px",
                    height: size === "xs" ? "12px" : size === "default" ? "16px" : "14px",
                  }}
                />
              ) : isIconOnly ? (
                <span className="flex items-center justify-center text-current">{item.icon}</span>
              ) : (
                <span
                  className={`inline-flex items-center justify-center gap-1.5 font-sans ${
                    size === "xs"
                      ? "text-[11.5px] font-medium"
                      : size === "default"
                        ? "text-[13px] font-medium"
                        : "text-xs font-medium"
                  }`}
                  style={{ whiteSpace: "nowrap" }}
                >
                  {item.icon && (
                    <span className="inline-flex shrink-0 items-center justify-center">
                      {item.icon}
                    </span>
                  )}
                  {item.label && <span className="shrink-0">{item.label}</span>}
                </span>
              )}
            </button>
          );
        })}
      </nav>
    </>
  );
}

